/* Painted character atlases. Entity x/y is always the contact point at the feet. */
MW.characterAssets={};
MW.characterReady=typeof Image==='undefined'?Promise.resolve():Promise.all(['characters','residents','creatures'].map(name=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{MW.characterAssets[name]=image;resolve();};image.onerror=()=>reject(new Error(name));image.src='assets/'+name+'-2d.webp?v=12';})));
(()=>{const R=MW.Renderer.prototype;
R.paintedCell=function(sheet,index,columns,rows,width,height){const sprite=this.art('painted12:'+sheet+':'+index+':'+width+':'+height,width*2,height*2,c=>{c.scale(2,2);const image=MW.characterAssets[sheet];if(!image)return;const sw=image.width/columns,sh=image.height/rows,sx=Math.floor(index%columns*sw),sy=Math.floor(Math.floor(index/columns)*sh),tmp=document.createElement('canvas');tmp.width=Math.floor(sw);tmp.height=Math.floor(sh);const t=tmp.getContext('2d');t.drawImage(image,sx,sy,tmp.width,tmp.height,0,0,tmp.width,tmp.height);const pixels=t.getImageData(0,0,tmp.width,tmp.height).data;let left=tmp.width,top=tmp.height,right=-1,bottom=-1;for(let y=0;y<tmp.height;y++)for(let x=0;x<tmp.width;x++)if(pixels[(y*tmp.width+x)*4+3]>45){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}if(right<left)return;const bw=right-left+1,bh=bottom-top+1,scale=Math.min((width-10)/bw,(height-4)/bh),dw=bw*scale,dh=bh*scale;c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';c.drawImage(tmp,left,top,bw,bh,(width-dw)/2,height-dh,dw,dh);});sprite.logicalWidth=width;sprite.logicalHeight=height;return sprite;};
R.hero=function(color='#739ba8',face=0,frame=0){const palette=['#c8b17b','#be81a1','#8a9ba5','#7bacc0','#a1b582','#c4a9d3','#b49b71','#c1a087'],index=Math.max(0,palette.indexOf(color));return this.paintedCell('residents',index,4,2,64,88);};
R.monster=function(type,region,boss=false){return this.paintedCell('creatures',Math.floor(region/4)*4+(boss?3:type%3),4,3,boss?120:74,boss?112:68);};
R.player=function(p,face=0,frame=0,pose=null){const job=Math.max(0,['traveler','warrior','archer','mage'].indexOf(p.job)),weapon=MW.items.find(i=>i.id===p.equip?.weapon),armor=MW.items.find(i=>i.id===p.equip?.armor),promoted=p.promotions?.includes(p.job),band=MW.auraBand(p);const key='paintedPlayer12:'+job+':'+face+':'+frame+':'+weapon?.id+':'+armor?.id+':'+promoted+':'+band+':'+(pose?.kind||'idle')+':'+(pose?.phase||0);if(pose&&pose.kind!=='idle'&&!this.atlas[key]){this.motionCache??=[];if(this.motionCache.length>=128)delete this.atlas[this.motionCache.shift()];this.motionCache.push(key);}const sprite=this.art(key,160,180,c=>{c.scale(2,2);c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';const drawGear=()=>{if(!weapon)return;c.save();if(face===3){c.translate(80,0);c.scale(-1,1);}if(pose){c.translate(62,54);c.rotate(MW.poseValues(pose).weapon);c.translate(-62,-54);}const color=['#b99c70','#85baa4','#aabfe1','#ecd08b'][(weapon.tier||1)-1],kind=weapon.kind||'sword',path=()=>{c.beginPath();if(kind==='bow'){c.moveTo(61,37);c.bezierCurveTo(78,45,78,67,61,76);}else{c.moveTo(62,kind==='staff'?27:33);c.lineTo(62,80);}};if(band){path();c.strokeStyle=band===2?'#ffe5a9':'#8de9f7';c.shadowColor=c.strokeStyle;c.shadowBlur=band===2?13:8;c.lineWidth=band===2?9:6;c.globalAlpha=.4;c.stroke();c.globalAlpha=1;c.shadowBlur=0;}path();c.lineCap='round';c.strokeStyle=kind==='sword'?'#384f60':'#544332';c.lineWidth=5;c.stroke();path();c.strokeStyle=kind==='sword'?'#e7eff3':color;c.lineWidth=2.5;c.stroke();if(kind==='bow'){c.beginPath();c.moveTo(61,37);c.lineTo(61,76);c.strokeStyle='#f2e7c9';c.lineWidth=.7;c.stroke();}else if(kind==='staff'){c.beginPath();c.ellipse(62,28,5,7,0,0,Math.PI*2);c.fillStyle='#5aa8c9';c.fill();c.strokeStyle=color;c.lineWidth=1.5;c.stroke();c.beginPath();c.ellipse(61,26,1.5,3,0,0,7);c.fillStyle='#dcffff';c.fill();}else{c.beginPath();c.moveTo(55,72);c.quadraticCurveTo(62,69,69,72);c.strokeStyle=color;c.lineWidth=3;c.stroke();c.beginPath();c.moveTo(62,73);c.lineTo(62,83);c.strokeStyle='#916f49';c.lineWidth=3;c.stroke();}c.restore();};if(face===2)drawGear();c.save();if(frame){c.translate(40,0);c.scale(1.018,1);c.translate(-40,0);}this.rigBody(c,this.paintedCell('characters',job*4+face,4,4,80,90),face,pose);c.restore();if(armor){c.save();if(face===3){c.translate(80,0);c.scale(-1,1);}const tier=armor.tier||1,col=['#788d9b','#609d85','#829ecd','#d2ba80'][tier-1],side=face===1||face===3,y=job===1?35:job===2?42:49;c.globalAlpha=.72;const fill=c.createLinearGradient(28,y,51,y+20);fill.addColorStop(0,'#e4edf0');fill.addColorStop(.35,col);fill.addColorStop(1,'#263745');c.fillStyle=fill;c.strokeStyle='#ddc595';c.lineWidth=.65;if(job===3){c.beginPath();c.moveTo(34,y);c.quadraticCurveTo(30,62,29,76);c.quadraticCurveTo(40,80,51,76);c.lineTo(46,y);c.lineTo(42,y+20);c.lineTo(39,y+20);c.closePath();c.fill();c.stroke();c.globalAlpha=1;c.beginPath();c.arc(40,57,1.5,0,7);c.fillStyle='#fff0c3';c.fill();}else{for(const x of side?[33]:[27,48]){c.beginPath();c.ellipse(x,y+2,4,3.5,0,0,7);c.fill();c.stroke();}c.beginPath();c.moveTo(side?35:32,y+4);c.quadraticCurveTo(40,y+7,side?43:48,y+4);c.lineTo(side?42:46,y+17);c.quadraticCurveTo(40,y+20,34,y+17);c.closePath();c.fill();c.stroke();c.beginPath();c.moveTo(34,y+6);c.lineTo(44,y+15);c.strokeStyle='#e2cfaa';c.lineWidth=job===2?2:.8;c.stroke();}c.restore();}if(promoted){c.beginPath();c.moveTo(25,44);c.quadraticCurveTo(40,49,54,44);c.strokeStyle='#f2d89b';c.lineWidth=1.8;c.stroke();}if(face!==2)drawGear();});sprite.logicalWidth=80;sprite.logicalHeight=90;return sprite;};
R.weaponSparkles=function(p,face=0){const band=MW.auraBand(p);if(!band)return;const c=this.ctx;c.save();for(let i=0;i<(band===2?7:4);i++){const phase=(this.time*.65+i*.23)%1,lx=62+Math.sin(i*2.4+this.time)*7,x=p.x-40+(face===3?80-lx:lx),y=p.y-90+82-phase*49;c.globalAlpha=Math.sin(phase*Math.PI)*.8;c.fillStyle=band===2?'#ffe4ab':'#aff3fc';c.beginPath();c.arc(x,y,band===2?1.4:1,0,7);c.fill();}c.restore();};
R.characterAt=function(sprite,x,y,width=sprite.logicalWidth||sprite.width,height=sprite.logicalHeight||sprite.height){this.ctx.save();this.ctx.imageSmoothingEnabled=true;this.ctx.imageSmoothingQuality='high';this.ctx.drawImage(sprite,x-width/2,y-height,width,height);this.ctx.restore();};
})();
